/// <summary>
/// Class that handles, when media files are being posted asynchronously to the backend from the device.
/// </summary>
class TFMDocPostMedia extends TFMDocumentHandler
{

}

Method.Source:
public Set getDocumentTypes()
{
    Set ret = new Set(Types::String);

    ret.add(methodStr(TFMDocPostMedia,PostMedia));

    return ret;
}

private void PostMedia()
{

    TFMMediaID              mediaID = request.getFieldValue('id');//requestXml.root().getNamedElement(TFMConstants::requestData()).getNamedElement('Id').innerText();
    str                     base64Img = request.getFieldValue('Data');// requestXml.root().getNamedElement(TFMConstants::requestData()).getNamedElement('Data').innerText();
    TFMMediaQueue::attachImage(mediaID, base64Img, request.parmdeviceID());

    resultStr = 'Image received';
}
